"""Checks for the SB.EXE lift. The listing itself is generated by tools/lift_sb.py."""
from __future__ import annotations

from pathlib import Path
import unittest

from tools.lift_sb import extract_descriptors, load_image


class LiftTests(unittest.TestCase):
    def test_string_pool_has_data_files(self) -> None:
        descs = extract_descriptors(load_image())
        texts = set(descs.values())
        for name in ("MONSTER.DAT", "ITEMFILE.DAT", "SPELLS.DAT", "USER.SBS"):
            self.assertIn(name, texts)

    def test_listing_has_translated_file_ops(self) -> None:
        listing = Path(__file__).resolve().parent.parent / "reconstructed" / "sb_lifted.bas"
        text = listing.read_text(encoding="utf-8")
        self.assertIn('OPEN "MONSTER.DAT" FOR RANDOM AS #2 LEN = 196', text)
        self.assertIn('OPEN "ITEMFILE.DAT" FOR RANDOM AS #1 LEN = 44', text)
        self.assertIn('OPEN "SPELLS.DAT" FOR RANDOM AS #6 LEN = 66', text)
        self.assertIn('OPEN "USER.SBS" FOR RANDOM AS #7 LEN = 87', text)
        self.assertIn('local_2E = "You have gone up a level!"', text)


if __name__ == "__main__":
    unittest.main()
